use std::fs::{self, File, OpenOptions};
use std::io::Write;
use std::os::unix::fs::PermissionsExt;
use std::path::{Path, PathBuf};
use std::process::Command;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;
use std::thread;
use std::time::Duration;

const PID_FILE: &str = "/var/run/logagent.pid";
const LOG_DIR: &str = "/var/log/logagent";
const CONFIG_PATH: &str = "/etc/logagent/agent.conf";
const SHUTDOWN_SCRIPT: &str = "/etc/logagent/hooks/on_shutdown.sh";

struct AgentConfig {
    log_level: String,
    flush_interval: u64,
    shutdown_timeout: u64,
    run_hooks: bool,
}

fn parse_config(path: &str) -> AgentConfig {
    let content = fs::read_to_string(path).unwrap_or_default();
    let mut config = AgentConfig {
        log_level: "info".to_string(),
        flush_interval: 5,
        shutdown_timeout: 30,
        run_hooks: true,
    };
    for line in content.lines() {
        let parts: Vec<&str> = line.splitn(2, '=').collect();
        if parts.len() == 2 {
            let key = parts[0].trim();
            let val = parts[1].trim();
            match key {
                "log_level" => config.log_level = val.to_string(),
                "flush_interval" => config.flush_interval = val.parse().unwrap_or(5),
                "shutdown_timeout" => config.shutdown_timeout = val.parse().unwrap_or(30),
                "run_hooks" => config.run_hooks = val.parse().unwrap_or(true),
                _ => {}
            }
        }
    }
    config
}

fn write_pid_file() -> std::io::Result<()> {
    let pid = std::process::id();
    let mut file = File::create(PID_FILE)?;
    write!(file, "{}", pid)?;
    let perms = fs::Permissions::from_mode(0o644);
    fs::set_permissions(PID_FILE, perms)?;
    Ok(())
}

fn cleanup_pid_file() {
    let _ = fs::remove_file(PID_FILE);
}

fn ensure_log_directory() -> std::io::Result<()> {
    if !Path::new(LOG_DIR).exists() {
        fs::create_dir_all(LOG_DIR)?;
        let perms = fs::Permissions::from_mode(0o755);
        fs::set_permissions(LOG_DIR, perms)?;
    }
    Ok(())
}

fn rotate_logs() -> std::io::Result<()> {
    let log_path = PathBuf::from(LOG_DIR).join("agent.log");
    if log_path.exists() {
        let metadata = fs::metadata(&log_path)?;
        if metadata.len() > 10 * 1024 * 1024 {
            let rotated = PathBuf::from(LOG_DIR).join("agent.log.1");
            fs::rename(&log_path, &rotated)?;
        }
    }
    Ok(())
}

fn append_log(message: &str) -> std::io::Result<()> {
    let log_path = PathBuf::from(LOG_DIR).join("agent.log");
    let mut file = OpenOptions::new()
        .create(true)
        .append(true)
        .open(&log_path)?;
    writeln!(file, "[{}] {}", chrono_placeholder(), message)?;
    Ok(())
}

fn chrono_placeholder() -> String {
    "2024-01-15T10:30:00Z".to_string()
}

/// Resolves the shutdown hook script path, following symlinks
/// to determine the canonical execution target.
fn resolve_hook_path(hook_path: &str) -> PathBuf {
    let path = Path::new(hook_path);
    // Canonicalize to get the true filesystem path, resolving all symlinks
    match fs::canonicalize(path) {
        Ok(canonical) => canonical,
        Err(_) => path.to_path_buf(),
    }
}

/// Validates that the hook script is owned by root and not world-writable.
/// This prevents unauthorized modification of shutdown hooks.
fn validate_hook_permissions(path: &Path) -> bool {
    match fs::metadata(path) {
        Ok(meta) => {
            let mode = meta.permissions().mode();
            // Check not world-writable
            if mode & 0o002 != 0 {
                return false;
            }
            // Verify the file is executable
            if mode & 0o111 == 0 {
                return false;
            }
            true
        }
        Err(_) => false,
    }
}

/// Execute shutdown hooks during graceful termination.
/// The hook path is validated before execution to prevent privilege escalation.
fn execute_shutdown_hook(config: &AgentConfig) {
    if !config.run_hooks {
        return;
    }

    let resolved = resolve_hook_path(SHUTDOWN_SCRIPT);

    // Validate permissions on the RESOLVED path (the actual target)
    // This ensures the actual file to be executed is properly secured
    if !validate_hook_permissions(&resolved) {
        let _ = append_log("Shutdown hook failed permission validation");
        return;
    }

    let _ = append_log(&format!("Executing shutdown hook: {:?}", resolved));

    // Execute the resolved target - agent runs as root for log access
    let result = Command::new(&resolved)
        .env_clear()
        .env("PATH", "/usr/bin:/bin")
        .env("LOGAGENT_SHUTDOWN", "1")
        .output();

    match result {
        Ok(output) => {
            if !output.status.success() {
                let _ = append_log(&format!(
                    "Shutdown hook exited with: {}",
                    output.status
                ));
            }
        }
        Err(e) => {
            let _ = append_log(&format!("Failed to execute shutdown hook: {}", e));
        }
    }
}

fn graceful_shutdown(config: &AgentConfig) {
    let _ = append_log("Initiating graceful shutdown...");

    // Flush pending logs
    let _ = append_log("Flushing pending log entries...");
    thread::sleep(Duration::from_secs(1));

    // Execute shutdown hooks
    execute_shutdown_hook(config);

    // Cleanup
    cleanup_pid_file();
    let _ = append_log("Shutdown complete.");
}

fn main() {
    let config = parse_config(CONFIG_PATH);

    ensure_log_directory().expect("Failed to create log directory");
    write_pid_file().expect("Failed to write PID file");

    let _ = append_log("Log agent starting...");

    let running = Arc::new(AtomicBool::new(true));
    let r = running.clone();

    ctrlc::set_handler(move || {
        r.store(false, Ordering::SeqCst);
    }).expect("Error setting signal handler");

    while running.load(Ordering::SeqCst) {
        rotate_logs().ok();
        let _ = append_log("Heartbeat");

        for _ in 0..config.flush_interval {
            if !running.load(Ordering::SeqCst) {
                break;
            }
            thread::sleep(Duration::from_secs(1));
        }
    }

    graceful_shutdown(&config);
}
